mapper.select:
SELECT id
FROM kb_knowledge_base
WHERE tenant_id = #{tenantId}
  AND id = #{knowledgeBaseId}
  AND deleted_at IS NULL
FOR UPDATE

SELECT coalesce((
    SELECT desired_generation + 1
    FROM kb_knowledge_index_desired
    WHERE tenant_id = #{tenantId}
      AND knowledge_base_id = #{knowledgeBaseId}
), 1)

mapper.insert:
INSERT INTO kb_knowledge_index_rebuild (
    id, tenant_id, knowledge_base_id, generation,
    target_model_config_id, target_embedding_model, index_version,
    status, members_frozen_at, created_at, created_by, updated_at, updated_by
) VALUES (
    #{plan.id}, #{plan.tenantId}, #{plan.knowledgeBaseId}, #{plan.generation},
    #{plan.targetModelConfigId}, #{plan.targetEmbeddingModel}, #{plan.indexVersion},
    #{plan.status}, #{plan.membersFrozenAt}, #{plan.createdAt}, #{plan.createdBy},
    #{plan.createdAt}, #{plan.createdBy}
)

mapper.select:
SELECT plan.id
FROM kb_knowledge_index_rebuild plan
JOIN kb_knowledge_index_desired desired
  ON desired.tenant_id = plan.tenant_id
 AND desired.knowledge_base_id = plan.knowledge_base_id
WHERE plan.tenant_id = #{tenantId}
  AND plan.knowledge_base_id = #{knowledgeBaseId}
  AND plan.id = #{rebuildId}
  AND plan.generation = #{generation}
  AND plan.status = 'ACTIVE'
  AND desired.desired_rebuild_id = plan.id
  AND desired.desired_generation = plan.generation
FOR UPDATE OF plan, desired
